// --- Opt-in logic, to be called after Marketo form is rendered ---

function setupOptinLogic() {
  console.log('batman22');
  // injectCustomCSS();
  attachCountryChangeHandler();

  // Optionally, auto-select country based on IP
  var token = '63de90678e0e7c';
  var xhr = new XMLHttpRequest();
  xhr.open('GET', 'https://ipinfo.io?token=' + token, true);
  xhr.onreadystatechange = function() {
    if (xhr.readyState === 4 && xhr.status === 200) {
      try {
        var data = JSON.parse(xhr.responseText);
        var countryArray = ["US", "CA", "GB", "BE", "FR", "NL", "SE", "IE", "PL", "HU", "FI", "PT"];
        var ipCountry = data.country;
        selectCountry(ipCountry);
        getOptInMsgBasedOnCountry(ipCountry, countryArray);
      } catch (e) {
        // Fail silently if IP detection fails
      }
    }
  };
  xhr.send();
}

// Select a country in the dropdown by code
function selectCountry(countryCode) {
  var selObj = document.getElementById('Country');
  if (selObj && countryCode) {
    for (var i = 0; i < selObj.options.length; i++) {
      if (selObj.options[i].value.toUpperCase() === countryCode.toUpperCase()) {
        selObj.selectedIndex = i;
        break;
      }
    }
  }
}

// Attach change handler to country dropdown
function attachCountryChangeHandler() {
  var selObj = document.getElementById('Country');
  if (selObj) {
    selObj.addEventListener('change', function(event) {
      var eventValue = 'true';
      var selCountryVal = selObj.value;
      if (selCountryVal) {
        var countryArray = ["US", "CA", "GB", "BE", "FR", "NL", "SE", "IE", "PL", "HU", "FI", "PT"];
        getOptInMsgBasedOnCountry(selCountryVal, countryArray, eventValue);
      }
    });
  }
}

// Remove all elements with a given ID (for dynamic opt-in message cleanup)
function removeAllById(id) {
  var elements = document.querySelectorAll('#' + id);
  elements.forEach(function(el) {
    el.parentNode.removeChild(el);
  });
}

// Helper to set value of hidden input by name
function setHiddenInputValue(name, value) {
  var input = document.querySelector('input[type="hidden"][name="' + name + '"]');
  if (input) input.value = value;
}

// Helper to find the form's .mktoButtonRow (for inserting opt-in message)
function getMktoButtonRow() {
  return document.querySelector('form.mktoForm .mktoButtonRow');
}

// Helper to hide parent .mktoFormRow of a checkbox
function hideOptinCheckboxRow() {
  var optinBox = document.getElementById('optinBox');
  if (optinBox) {
    var row = optinBox.closest('.mktoFormRow');
    if (row) row.style.display = 'none';
  }
}

// Helper to show optin checkbox
function showOptinCheckbox() {
  var optinBox = document.getElementById('optinBox');
  if (optinBox) optinBox.style.display = '';
}

// Helper to hide address field
function hideAddress() {
  var addr = document.getElementById('c-address');
  if (addr) addr.style.display = 'none';
}

// Main opt-in message logic
function getOptInMsgBasedOnCountry(country, countryArray, eventValue) {
  if (eventValue) {
    removeAllById('checkLabelDiv');
    // Remove any previous event listeners by cloning node
    var oldOptinBox = document.getElementById('optinBox');
    if (oldOptinBox) {
      var newOptinBox = oldOptinBox.cloneNode(true);
      oldOptinBox.parentNode.replaceChild(newOptinBox, oldOptinBox);
    }
  }

  // US: implicit opt-in, hide checkbox and address
  if (country === "US" && countryArray.indexOf(country) > -1) {
    setHiddenInputValue('tempImplicitOptin', 'Yes');
    hideOptinCheckboxRow();
    hideAddress();
    return;
  }

  // Canada: explicit opt-in, show checkbox and message
  if (country === "CA" && countryArray.indexOf(country) > -1) {
    setHiddenInputValue('tempImplicitOptin', 'No');
    var optinCheckbox = document.createElement('div');
    optinCheckbox.className = 'mktoFormRow';
    optinCheckbox.id = 'checkLabelDiv';
    optinCheckbox.innerHTML =
      '<div class="mktoGutter mktoHasWidth" style="width: 0px;"></div>' +
      '<div class="mktoLogicalField mktoCheckboxList mktoHasWidth" style="width: auto;float: inherit !important;">' +
      '<input name="optinBox" id="optinBox" type="checkbox" value="No" class="mktoField" style="margin-left: 0px;width: auto !important;">' +
      '<label for="optinBox" class="optIn" style="margin-left: 20px !important;display: block;margin-bottom: 20px !important;">' +
      'I agree to receive emails from Cvent, Inc. about relevant content, products, and services. I understand I can manage my communication preferences or ' +
      '<a href="//hello.cvent.com/subscriptionmanagement" style="color: #0080ee!important;">unsubscribing</a> at any time.<br/><br/>' +
      'Please refer to our <a href="//www.cvent.com/en/privacy-policy.shtml" target="_blank" style="color: #0080ee!important;">Privacy Policy</a> or ' +
      '<a href="mailto:privacy@cvent.com" target="_blank" style="color: #0080ee!important;">Contact Us</a> for more details.<br><br>' +
      'Cvent, Inc. 1765 Greensboro Station Place 7th Floor,<br>Tysons Corner,<br>VA 22102</label>' +
      '</div>';
    var buttonRow = getMktoButtonRow();
    if (buttonRow) buttonRow.parentNode.insertBefore(optinCheckbox, buttonRow);

    // Add event listener to checkbox
    var optinBox = document.getElementById('optinBox');
    if (optinBox) {
      optinBox.addEventListener('click', function() {
        setHiddenInputValue('tempImplicitOptin', this.checked ? 'Yes' : 'No');
      });
      showOptinCheckbox();
    }
    return;
  }

  // EU/UK countries: implicit opt-in, show message (no checkbox)
  if (["GB", "FR", "SE", "IE", "PL", "HU", "BE", "FI", "PT"].indexOf(country) > -1 && countryArray.indexOf(country) > -1) {
    setHiddenInputValue('tempImplicitOptin', 'Yes');
    var optinCheckbox = document.createElement('div');
    optinCheckbox.className = 'mktoFormRow';
    optinCheckbox.id = 'checkLabelDiv';
    optinCheckbox.innerHTML =
      '<div class="mktoGutter mktoHasWidth" style="width: 0px;"></div>' +
      '<div class="mktoLogicalField mktoCheckboxList mktoHasWidth" style="width: auto;float: inherit !important;">' +
      '<label for="optinBox" class="optIn" style="margin-left: 20px !important;display: block;margin-bottom: 20px !important;">' +
      'I agree to receive emails from Cvent, Inc. about relevant content, products, and services. I understand I can manage my communication preferences or ' +
      '<a href="//hello.cvent.com/subscriptionmanagement" style="color: #0080ee!important;">unsubscribing</a> at any time.<br><br/>' +
      'Please refer to our <a href="//www.cvent.com/en/privacy-policy.shtml" target="_blank" style="color: #0080ee!important;">Privacy Policy</a> or ' +
      '<a href="mailto:privacy@cvent.com" target="_blank" style="color: #0080ee!important;">Contact Us</a> for more details.</label>' +
      '</div>';
    var buttonRow = getMktoButtonRow();
    if (buttonRow) buttonRow.parentNode.insertBefore(optinCheckbox, buttonRow);
    return;
  }

  // All other countries: explicit opt-in, show checkbox and message
  setHiddenInputValue('tempImplicitOptin', 'No');
  var optinCheckbox = document.createElement('div');
  optinCheckbox.className = 'mktoFormRow';
  optinCheckbox.id = 'checkLabelDiv';
  optinCheckbox.innerHTML =
    '<div class="mktoGutter mktoHasWidth" style="width: 0px;"></div>' +
    '<div class="mktoLogicalField mktoCheckboxList mktoHasWidth" style="width: auto;float: inherit !important;">' +
    '<input name="optinBox" id="optinBox" type="checkbox" value="No" class="mktoField" style="margin-left: 0px;width: auto !important;">' +
    '<label for="optinBox" class="optIn" style="margin-left: 20px !important;display: block;margin-bottom: 20px !important;">' +
    'I agree to receive emails from Cvent, Inc. about relevant content, products, and services. I understand I can manage my communication preferences or ' +
    '<a href="//hello.cvent.com/subscriptionmanagement" style="color: #006ae1!important;">unsubscribing</a> at any time.<br/><br/>' +
    'Please refer to our <a href="//www.cvent.com/en/privacy-policy.shtml" target="_blank" style="color: #006ae1!important;">Privacy Policy</a> or ' +
    '<a href="mailto:privacy@cvent.com" target="_blank" style="color: #006ae1!important;">Contact Us</a> for more details.</label>' +
    '</div>';
  var buttonRow = getMktoButtonRow();
  if (buttonRow) buttonRow.parentNode.insertBefore(optinCheckbox, buttonRow);

  // Add event listener to checkbox
  var optinBox = document.getElementById('optinBox');
  if (optinBox) {
    optinBox.addEventListener('click', function() {
      setHiddenInputValue('tempImplicitOptin', this.checked ? 'Yes' : 'No');
    });
    showOptinCheckbox();
  }
}

