// Utility: Mark input as valid/invalid
function markValidity(input, isValid) {
  if (isValid) {
    input.classList.remove("mktoInvalid");
    input.classList.add("mktoValid");
  } else {
    input.classList.add("mktoInvalid");
    input.classList.remove("mktoValid");
  }
}

// Validate all fields individually
function setupFieldValidation(inputId) {
  const input = document.getElementById(inputId);
  if (!input) return;

  function validate() {
    const value = input.value.trim().toLowerCase();
    let isValid = true;
    if(!value){
      isValid = false;
      return;
    }

    // Email-specific validation
    if (inputId === "Email") {
      const [localPart] = value.split('@');
      isValid = !isExcludedDomain(value) && !containsBadWord(localPart);
    } else {
      isValid = !containsBadWord(value);
    }

    markValidity(input, isValid);
    validateForm(); // Update submit button state
  }

  input.addEventListener("blur", validate);
  input.addEventListener("keyup", validate);
}

// Enable/disable submit button based on field validity
function validateForm() {
  const submitBtn = document.querySelector('.mktoButton');
  const invalidFields = document.querySelectorAll('.mktoInvalid');
  if (invalidFields.length > 0) {
   if (submitBtn) {
  submitBtn.setAttribute('disabled', 'disabled');
}
  } else {
     if (submitBtn) {
  submitBtn.removeAttribute('disabled');
     }
  }
}

// Final validation on form submission
function validateFormOnSubmit(form) {
  let hasError = false;

  // Validate each field one more time before submit
  ["FirstName", "LastName", "Email", "Company"].forEach((id) => {
    const input = document.getElementById(id);
    if (!input) return;

    const value = input.value.trim().toLowerCase();
    if (!value) {
      hasError = true;
      return;
    };

    let isValid = true;

    if (id === "Email") {
      const [localPart] = value.split('@');
      isValid = !isExcludedDomain(value) && !containsBadWord(localPart);
    } else {
      isValid = !containsBadWord(value);
    }

    markValidity(input, isValid);

    if (!isValid) hasError = true;
  });

  validateForm(); // Update button just in case

  if (hasError) {
    console.log('Form contains invalid fields. Please correct them.');
    form.submittable(false);
    return;
  }

  // Show loader if no errors
  const loader = document.getElementById('loader');
  if(loader){
loader.classList.remove('d-none');
  }
}

// Initialize form logic
function initializeForm() {
  if (typeof MktoForms2 === 'undefined') return;

  MktoForms2.loadForm("//hello.cvent.com", "006-LRT-285", 14582, function(form) {
    // Setup validations
    setupFieldValidation("FirstName");
    setupFieldValidation("LastName");
	setupFieldValidation("Phone");
    setupFieldValidation("Email");
    setupFieldValidation("Company");

    // On form success (submission passed)
    form.onSuccess(function(values, followUpUrl) {
      formCookie(); // Assuming this function exists
      window.open("https://www.cvent.com/sites/default/files/files/2025-08/Meet%20Smarter%20Engage%20Deeper%20-%20Your%20Guide%20to%20Driving%20Engagement%20Through%20Events.pdf", "_blank");
    });

    // Hook into the submit button click
    const submitBtn = document.querySelector('button.mktoButton');
    if (submitBtn) {
      submitBtn.onclick = function() {
        validateFormOnSubmit(form);
      };
    }
  });

  MktoForms2.whenReady(function(form) {
    setupOptinLogic(); // Assuming this function exists
  });
}


// Dynamically load an external script
function loadScript(url, callback) {
  const script = document.createElement('script');
  script.src = url;
  script.async = true;
  script.onload = callback;
  script.onerror = () => console.error(`Failed to load script: ${url}`);
  document.head.appendChild(script);
}

// Load the MktoForm script if needed
function loadMktoForm() {
  loadScript('https://hello.cvent.com/rs/006-LRT-285/images/master-ex-domain-list-cc.js?version=1', () => {
    if (typeof MktoForms2 === 'undefined') {
      loadScript('//hello.cvent.com/js/forms2/js/forms2.min.js', initializeForm);
    } else {
      initializeForm();
    }
  });
}

// Main entry point: waits for modal and form elements, then loads everything
function runWhenReady() {
  const openBtn = document.getElementById('openModalBtn');
  const modal = document.getElementById('marketoModal');
  const formModalShow = document.querySelector('.modal-content-form');
  const thankModal = document.querySelector('.modal-content-thanks');
  const closeBtn = document.getElementById('closeModalBtn');

  // Retry until all elements are available
  if (!openBtn || !modal || !closeBtn) {
    setTimeout(runWhenReady, 100);
    return;
  }

  loadMktoForm();
  setupModal(openBtn, modal, closeBtn);

  // Handle modal visibility based on cookie
  if (getCookie('resourceForm')) {
    if (formModalShow) formModalShow.style.display = 'none';
  } else {
    if (thankModal) thankModal.style.display = 'none';
  }
}


runWhenReady();
