// --- Opt-in logic, to be called after Marketo form is rendered ---

function setupOptinLogic() {
  console.log('batman22');
  // injectCustomCSS();
  attachCountryChangeHandler();

  // Optionally, auto-select country based on IP
  var token = '63de90678e0e7c';
  var xhr = new XMLHttpRequest();
  xhr.open('GET', 'https://ipinfo.io?token=' + token, true);
  xhr.onreadystatechange = function() {
    if (xhr.readyState === 4 && xhr.status === 200) {
      try {
        var data = JSON.parse(xhr.responseText);
        var countryArray = ["US", "CA", "GB", "BE", "FR", "NL", "SE", "IE", "PL", "HU", "FI", "PT"];
        var ipCountry = data.country;
        selectCountry(ipCountry);
        getOptInMsgBasedOnCountry(ipCountry, countryArray);
      } catch (e) {
        // Fail silently if IP detection fails
      }
    }
  };
  xhr.send();
}

// Select a country in the dropdown by code
function selectCountry(countryCode) {
  var selObj = document.getElementById('Country');
  if (selObj && countryCode) {
    for (var i = 0; i < selObj.options.length; i++) {
      if (selObj.options[i].value.toUpperCase() === countryCode.toUpperCase()) {
        selObj.selectedIndex = i;
        break;
      }
    }
  }
}

// Attach change handler to country dropdown
function attachCountryChangeHandler() {
  var selObj = document.getElementById('Country');
  if (selObj) {
    selObj.addEventListener('change', function(event) {
      var eventValue = 'true';
      var selCountryVal = selObj.value;
      if (selCountryVal) {
        var countryArray = ["US", "CA", "GB", "BE", "FR", "NL", "SE", "IE", "PL", "HU", "FI", "PT"];
        getOptInMsgBasedOnCountry(selCountryVal, countryArray, eventValue);
      }
    });
  }
}

// Remove all elements with a given ID (for dynamic opt-in message cleanup)
function removeAllById(id) {
  var elements = document.querySelectorAll('#' + id);
  elements.forEach(function(el) {
    el.parentNode.removeChild(el);
  });
}

// Helper to set value of hidden input by name
function setHiddenInputValue(name, value) {
  var input = document.querySelector('input[type="hidden"][name="' + name + '"]');
  if (input) input.value = value;
}

