// Handle modal open/close functionality
function setupModal(openBtn, modal, closeBtn) {
  openBtn.onclick = () => modal.style.display = 'flex';
  closeBtn.onclick = () => modal.style.display = 'none';

  const closeBtn2 = document.getElementById('closeModalBtn2');
  if (closeBtn2) closeBtn2.onclick = () => modal.style.display = 'none';

  // Close modal when clicking outside the modal
  window.onclick = function(event) {
    if (event.target === modal) {
      modal.style.display = 'none';
    }
  };
}

// Set a cookie with a specific expiration date
function setCookie(name, value, days) {
  const date = new Date();
  date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
  const expires = `expires=${date.toUTCString()}`;
  document.cookie = `${name}=${value};${expires};path=/`;
}

// Store a flag cookie when the form is submitted
function formCookie() {
  setCookie("resourceForm", "true", 7);
}

// Get the value of a specific cookie
function getCookie(name) {
  const cookies = document.cookie.split(';');
  for (let i = 0; i < cookies.length; i++) {
    let c = cookies[i].trim();
    if (c.indexOf(name + "=") === 0) {
      return c.substring(name.length + 1);
    }
  }
  return null;
}


